WITH prod AS (
  SELECT probability_fraud AS val
  FROM fraud_detection_dev.gold.model_predictions WHERE probability_fraud IS NOT NULL
), ranked AS (
  SELECT val, ROW_NUMBER() OVER (ORDER BY val) AS rn, COUNT(*) OVER () AS n
  FROM prod
), binned AS (
  SELECT ROUND(val, 3) AS prob_bin, MAX(rn * 1.0 / n) AS cdf
  FROM ranked GROUP BY ROUND(val, 3)
) SELECT 'Producao' AS source, prob_bin AS prob_value, cdf FROM binned
